#!/usr/bin/env node
/**
 * build-content.mjs — the docs content pipeline.
 *
 * Parses the committed docs/{en,zh}/**.md pages (plus the changelog mirrors
 * regenerated by sync-changelog.mjs) into pre-rendered JSON under
 * src/.content/ (gitignored):
 *
 *   pages/<locale>/<slug>.json   one entry per route — frontmatter, fully
 *                                rendered HTML (shiki-highlighted fences,
 *                                admonitions, resolved internal links), TOC,
 *                                and — for the changelog — a structured
 *                                versions[] timeline payload.
 *   manifest.json                route table for the React shell (titles,
 *                                descriptions, TOC, git last-updated dates).
 *   search-{en,zh}.json          serialized MiniSearch indexes, one per locale
 *                                (CJK text is bigram-tokenized in processTerm).
 *
 * The published route set is DERIVED from scripts/navigation.mjs: pages on
 * disk that no nav/sidebar link reaches are not published (the internal
 * plans/ tree lives outside en/zh; en|zh/testing/ is currently unreached).
 *
 * Hard invariants (the retired VitePress config kept dead-link checking on
 * with no ignoreDeadLinks — same spirit):
 *   - a nav/sidebar link whose .md file is missing fails the build;
 *   - an internal content link to a page outside the route set fails the
 *     build, with every offender listed;
 *   - same-page anchors are validated against the target page's heading ids
 *     and reported as warnings (soft — heading drift should be visible, not
 *     release-blocking).
 */
import fs from 'node:fs/promises'
import path from 'node:path'
import { execFileSync } from 'node:child_process'
import { fileURLToPath, pathToFileURL } from 'node:url'
import matter from 'gray-matter'
import { Marked } from 'marked'
import GithubSlugger from 'github-slugger'
import MiniSearch from 'minisearch'
import { createHighlighter } from 'shiki'
import { en as enNav, zh as zhNav } from './navigation.mjs'

export const DOCS_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const CONTENT_DIR = 'src/.content'
const LOCALES = ['en', 'zh']
const SITE_URL = 'https://muskstark.github.io/FengYu/'

/** Shiki themes: the warm vitesse pair sits well on the gold/off-white palette; switched by the `.dark` class. */
const CODE_THEME_LIGHT = 'vitesse-light'
const CODE_THEME_DARK = 'vitesse-dark'
const SHIKI_LANGS = ['bash', 'json', 'jsonc', 'java', 'javascript', 'typescript', 'tsx', 'html', 'yaml', 'plaintext']
const LANG_ALIASES = {
  text: 'plaintext', txt: 'plaintext', sh: 'bash', shell: 'bash', console: 'bash',
  cjs: 'javascript', mjs: 'javascript', js: 'javascript', ts: 'typescript',
  yml: 'yaml', md: 'markdown', '': 'plaintext',
}

/** Localized default admonition titles (a `::: tip Custom title` form overrides). */
export const NOTE_TITLES = {
  en: { tip: 'Tip', info: 'Info', note: 'Note', warning: 'Warning', danger: 'Danger' },
  zh: { tip: '提示', info: '信息', note: '注', warning: '警告', danger: '危险' },
}

/** Localized heading for the condensed prerelease rollup inside a stable entry. */
export const PRERELEASE_TITLES = { en: 'Prerelease changes', zh: '预发布版本变更' }

export function escapeHtml(value) {
  return String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}

/** Normalize raw inline markdown of a heading into the plain text github-slugger saw under VitePress (code ticks, links, emphasis stripped). */
export function headingPlainText(raw) {
  return String(raw)
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/[`*_~]/g, '')
    .trim()
}

export function stripTags(html) {
  return String(html).replace(/<[^>]+>/g, ' ')
}

/** Normalize a nav/content link to its canonical SPA route: '/en/skills/' → '/en/skills', '/en/' → '/en'. */
export function normalizeRoutePath(routePath) {
  const withoutHash = routePath.split('#')[0]
  const collapsed = withoutHash.replace(/\/+$/, '')
  return collapsed === '' ? withoutHash : collapsed
}

/**
 * Resolve an href found in page content against the page it appears on.
 * Returns { kind: 'external' | 'anchor' | 'internal' | 'other', href?, path?, hash? } —
 * internal paths are canonical routes; relative .md links are resolved
 * file-relative first (VitePress-era content carries `./x.md` / `../y.md`).
 */
export function resolveHref(href, pageKey) {
  if (/^(https?:|mailto:)/i.test(href)) return { kind: 'external', href }
  if (href.startsWith('#')) return { kind: 'anchor', hash: href.slice(1) }
  if (href.startsWith('/en/') || href.startsWith('/zh/') || href === '/en' || href === '/zh') {
    const [rawPath, rawHash = ''] = href.split('#')
    const routePath = rawPath.length > '/en'.length ? rawPath.replace(/\/+$/, '') : rawPath
    return { kind: 'internal', path: routePath, hash: rawHash }
  }
  if (/\.md(?:#|$)/.test(href)) {
    const [rel, hash = ''] = href.split('#')
    const fromDir = path.posix.dirname(pageKey)
    const targetKey = path.posix.normalize(path.posix.join(fromDir, rel))
    if (!LOCALES.includes(targetKey.split('/')[0])) return { kind: 'other', href }
    const withoutExt = targetKey.replace(/\.md$/, '')
    const routePath = withoutExt.endsWith('/index') ? withoutExt.slice(0, -'/index'.length) : withoutExt
    return { kind: 'internal', path: `/${routePath}`, hash }
  }
  return { kind: 'other', href }
}

/**
 * Admonition containers (`::: tip [title]` … `:::`), the only VitePress-flavored
 * markdown the content uses. A block-level extension tokenizes the inner body
 * with the normal block rules, so containers nest code fences and tables.
 */
export function admonitionExtension(locale) {
  return {
    name: 'admonition',
    level: 'block',
    start(src) {
      return src.match(/^:::/m)?.index
    },
    tokenizer(src) {
      const rule = /^:::[ \t]*(tip|info|note|warning|danger)[ \t]*([^\n]*)\n([\s\S]*?)\n?:::[ \t]*(?=\n|$)/
      const match = rule.exec(src)
      if (!match) return undefined
      return {
        type: 'admonition',
        raw: match[0],
        kind: match[1].toLowerCase(),
        customTitle: match[2].trim(),
        locale,
        tokens: this.lexer.blockTokens(match[3]),
      }
    },
    renderer(token) {
      const body = this.parser.parse(token.tokens)
      const title = token.customTitle || NOTE_TITLES[token.locale]?.[token.kind] || token.kind
      return `<aside class="doc-note doc-note--${escapeHtml(token.kind)}"><p class="doc-note-title">${escapeHtml(title)}</p>${body}</aside>`
    },
  }
}

/** Renderers capture page-scoped context (slugger, headings, links) and the shared highlight cache. The code renderer is a SYNC lookup into a pre-highlighted map (see renderMarkdown) — marked's async renderer path stringifies promises in practice. */
function makeRenderers(ctx) {
  return {
    heading(token) {
      const inner = this.parser.parseInline(token.tokens)
      const plain = headingPlainText(token.text)
      const id = ctx.slugger.slug(plain)
      ctx.headings.push({ depth: token.depth, text: plain, id })
      return `<h${token.depth} id="${escapeHtml(id)}">${inner}<a class="doc-hanchor" href="#${escapeHtml(id)}" aria-label="Link to this section">#</a></h${token.depth}>`
    },
    code(token) {
      const lang = String(token.lang || '').split(/\s+/)[0]
      const html =
        ctx.highlighted.get(`${lang}::${token.text}`) ??
        `<pre><code class="language-${escapeHtml(lang || 'text')}">${escapeHtml(token.text)}</code></pre>`
      const label = lang || 'text'
      return `<figure class="doc-code" data-lang="${escapeHtml(label)}"><figcaption class="doc-code-head"><span class="doc-code-lang">${escapeHtml(label)}</span></figcaption>${html}</figure>`
    },
    link(token) {
      const inner = this.parser.parseInline(token.tokens ?? [])
      const resolved = resolveHref(token.href, ctx.pageKey)
      if (resolved.kind === 'internal') {
        ctx.links.push({ ...resolved, raw: token.href })
        const href = resolved.hash ? `${resolved.path}#${resolved.hash}` : resolved.path
        return `<a href="${escapeHtml(href)}">${inner}</a>`
      }
      if (resolved.kind === 'external') {
        return `<a href="${escapeHtml(token.href)}" target="_blank" rel="noopener">${inner}</a>`
      }
      return `<a href="${escapeHtml(token.href)}">${inner}</a>`
    },
  }
}

function walkTokens(tokens, visit) {
  for (const token of tokens) {
    visit(token)
    if (token.tokens) walkTokens(token.tokens, visit)
    if (token.items) walkTokens(token.items, visit)
  }
}

/**
 * Render one markdown chunk: lex → pre-highlight every fence (deduped via the
 * shared cache) → parse synchronously. `ctx.dropTitleHeading` strips a
 * leading `# H1` whose text duplicates the frontmatter title (the app shell
 * renders its own display-font H1; the heading's slug is returned so the
 * shell can keep the historical `#page-title` anchor alive).
 */
async function renderMarkdown(md, ctx, markdown, { dropTitleHeading = false } = {}) {
  const tokens = md.lexer(markdown)
  let titleId = null
  const firstMeaningful = tokens.findIndex((token) => token.type !== 'space')
  if (dropTitleHeading && tokens[firstMeaningful]?.type === 'heading' && tokens[firstMeaningful].depth === 1) {
    titleId = ctx.slugger.slug(headingPlainText(tokens[firstMeaningful].text))
    tokens.splice(firstMeaningful, 1)
  }
  const fences = []
  walkTokens(tokens, (token) => {
    if (token.type === 'code') fences.push(token)
  })
  for (const token of fences) {
    const lang = String(token.lang || '').split(/\s+/)[0]
    ctx.highlighted.set(`${lang}::${token.text}`, await ctx.highlight(lang, token.text))
  }
  return { html: md.parser(tokens), titleId }
}

/** Split a changelog body into intro + `## [version] — date` sections (the sync script's heading contract; the date segment is optional). */
export function splitChangelog(body) {
  const lines = body.split('\n')
  const sections = []
  const intro = []
  let current = null
  const heading = /^## \[([^\]]+)\](?:\s+[—-]\s+([^\n]+?))?\s*$/
  for (const line of lines) {
    const match = heading.exec(line)
    if (match) {
      if (current) sections.push(current)
      current = { version: match[1], date: (match[2] || '').trim(), body: [] }
    } else if (current) {
      current.body.push(line)
    } else {
      intro.push(line)
    }
  }
  if (current) sections.push(current)
  return { intro: intro.join('\n'), sections }
}

/** Only DATED sections are released versions. Undated headings (`[Unreleased]`) are the root CHANGELOG's working area and never publish to the site. */
export function releasedSections(sections) {
  return sections.filter((section) => section.date)
}

/** Version base line: '4.0.0-rc.3' → '4.0.0', '4.0.1' → '4.0.1' (non-semver ids pass through). */
export function releaseBase(version) {
  return /^(\d+\.\d+\.\d+)/.exec(version)?.[1] ?? version
}

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/

/**
 * Condense one prerelease body to its change headlines — the bold lead of each
 * bullet (this changelog's house style: `**Summary.** Explanation…`), or the
 * first sentence when a bullet has no bold lead. Prose paragraphs and the
 * per-section type headings are dropped: the condensed rollup is a one-line
 * list of what changed, not a re-narration.
 */
export function condensePrerelease(bodyLines) {
  const headlines = []
  let bullet = null
  const flush = () => {
    if (bullet === null) return
    const joined = bullet.replace(/\s+/g, ' ').trim()
    const bold = /\*\*(.+?)\*\*/.exec(joined)
    const text = (bold ? bold[1] : joined.split('. ')[0] || joined).trim()
    if (text) headlines.push(text)
    bullet = null
  }
  for (const line of bodyLines) {
    if (/^#{1,6}\s/.test(line)) {
      flush()
      continue
    }
    if (/^[-*]\s+/.test(line)) {
      flush()
      bullet = line.replace(/^[-*]\s+/, '')
      continue
    }
    if (bullet !== null) {
      if (line.trim() === '') flush()
      else bullet += ` ${line.trim()}`
    }
  }
  flush()
  return headlines
}

/**
 * Collapse the dated changelog sections into release LINES (house convention:
 * when a stable version ships, its entry carries the whole prerelease cycle).
 * Per line, newest section first as the file lists them:
 *   - a line WITH a stable section publishes as the stable version, absorbing
 *     every prerelease of the line as condensed headlines;
 *   - a line still in flight (no stable yet) publishes its NEWEST prerelease
 *     entry as-is, absorbing the older ones;
 *   - the line's display date is the newest ISO date inside it (tolerates the
 *     historical mid-cycle misplacement of `## [4.0.0]` — dated 2026-07-29
 *     while alpha.5–rc.3 follow it in the file).
 */
export function mergeReleaseLines(sections) {
  const order = []
  const groups = new Map()
  for (const section of sections) {
    const base = releaseBase(section.version)
    if (!groups.has(base)) {
      groups.set(base, { base, stable: null, pres: [], newestDate: '' })
      order.push(base)
    }
    const group = groups.get(base)
    if (section.version === base) {
      if (!group.stable) group.stable = section
    } else {
      group.pres.push(section)
    }
    if (ISO_DATE.test(section.date) && section.date > group.newestDate) group.newestDate = section.date
  }
  return order.map((base) => {
    const group = groups.get(base)
    const head = group.stable ?? group.pres[0]
    const absorbed = group.stable ? group.pres : group.pres.slice(1)
    const headlines = []
    const seen = new Set()
    for (const pre of absorbed) {
      for (const headline of condensePrerelease(pre.body)) {
        const key = headline.toLowerCase()
        if (seen.has(key)) continue
        seen.add(key)
        headlines.push(headline)
      }
    }
    return {
      version: head.version,
      date: group.newestDate || head.date,
      body: head.body,
      headlines,
    }
  })
}

/** CJK text has no spaces: tokenize as character bigrams so MiniSearch can match inside runs (array return is its sanctioned multi-term form). */
export function cjkProcessTerm(term) {
  const text = String(term).toLowerCase()
  if (!/[\u4e00-\u9fff]/.test(text)) return text || null
  if (text.length <= 2) return [text]
  const grams = []
  for (let i = 0; i < text.length - 1; i += 1) grams.push(text.slice(i, i + 2))
  return grams
}

function lastUpdatedFor(root, file) {
  try {
    return execFileSync('git', ['log', '-1', '--format=%cI', '--', path.relative(root, file)], { cwd: root }).toString().trim() || null
  } catch {
    return null
  }
}

/** Nav link → { routePath, pageKeys, locale }: a route may be a leaf page ('en/quickstart.md') or a directory index ('en/skills/index.md'); the build picks whichever exists. */
export function linkTarget(link) {
  const routePath = normalizeRoutePath(link)
  const locale = routePath.split('/')[1]
  const rest = routePath.slice(`/${locale}`.length).replace(/^\//, '')
  const pageKeys = rest === '' ? [`${locale}/index.md`] : [`${locale}/${rest}.md`, `${locale}/${rest}/index.md`]
  return { routePath, pageKeys, locale }
}

async function collectRoutes(root) {
  const routes = new Map()
  const order = []
  const breadcrumbs = new Map() // routePath → sidebar group label
  const exists = async (pageKey) => {
    try {
      await fs.access(path.join(root, pageKey))
      return true
    } catch {
      return false
    }
  }
  for (const locale of LOCALES) {
    const nav = locale === 'en' ? enNav : zhNav
    for (const link of [...nav.nav, ...nav.sidebar.flatMap((group) => group.items)]) {
      const { routePath, pageKeys } = linkTarget(link.link)
      if (routes.has(routePath)) continue
      let pageKey = null
      for (const candidate of pageKeys) {
        if (await exists(candidate)) {
          pageKey = candidate
          break
        }
      }
      routes.set(routePath, { pageKey, pageKeys, locale })
      order.push(routePath)
    }
    for (const group of nav.sidebar) {
      for (const item of group.items) {
        const { routePath } = linkTarget(item.link)
        if (!breadcrumbs.has(routePath)) breadcrumbs.set(routePath, group.text)
      }
    }
  }
  return { routes, order, breadcrumbs }
}

function buildSearchIndex(docs) {
  const mini = new MiniSearch({
    fields: ['title', 'headings', 'body'],
    storeFields: ['title', 'breadcrumb'],
    processTerm: cjkProcessTerm,
  })
  mini.addAll(docs)
  return { index: mini.toJSON(), generatedAt: new Date().toISOString() }
}

/**
 * @param {string} [root] - docs root (defaults to this script's parent)
 * @param {{ quiet?: boolean }} [options]
 * @returns {Promise<{ pages: number, deadLinks: number, anchorWarnings: number, unlisted: string[] }>}
 */
export async function buildContent(root = DOCS_ROOT, { quiet = false } = {}) {
  const log = (...args) => { if (!quiet) console.log('[content]', ...args) }
  const { routes, order, breadcrumbs } = await collectRoutes(root)

  const highlighter = await createHighlighter({ themes: [CODE_THEME_LIGHT, CODE_THEME_DARK], langs: SHIKI_LANGS })
  const highlightCache = new Map()
  async function highlight(lang, code) {
    const key = `${lang}::${code}`
    if (highlightCache.has(key)) return highlightCache.get(key)
    const resolved = LANG_ALIASES[lang] ?? lang
    const use = highlighter.getLoadedLanguages().includes(resolved) ? resolved : 'plaintext'
    const html = await highlighter.codeToHtml(code, { lang: use, themes: { light: CODE_THEME_LIGHT, dark: CODE_THEME_DARK } })
    highlightCache.set(key, html)
    return html
  }

  const missingFiles = []
  const deadPages = []   // { from, link }
  const anchorWarns = [] // { from, target, hash }
  const unlisted = new Set()
  for (const locale of LOCALES) {
    const base = path.join(root, locale)
    const files = await fs.readdir(base, { recursive: true })
    for (const file of files) {
      const rel = String(file).replace(/\\/g, '/')
      if (rel.endsWith('.md')) unlisted.add(`${locale}/${rel}`)
    }
  }

  const pageEntries = []
  const routeMeta = {}
  const headingIds = new Map()
  const allLinks = []
  const searchDocs = { en: [], zh: [] }

  for (const routePath of order) {
    const { pageKey, pageKeys, locale } = routes.get(routePath)
    const file = pageKey ? path.join(root, pageKey) : null
    let raw
    if (!file) {
      missingFiles.push({ routePath, pageKey: pageKeys.join(' | ') })
      continue
    }
    try {
      raw = await fs.readFile(file, 'utf8')
    } catch {
      missingFiles.push({ routePath, pageKey })
      continue
    }
    unlisted.delete(pageKey)

    const { data: frontmatter, content: body } = matter(raw)
    const isChangelog = pageKey === `${locale}/reference/changelog.md`
    const ctx = {
      pageKey,
      slugger: new GithubSlugger(),
      headings: [],
      links: [],
      highlighted: highlightCache,
      highlight,
    }
    const md = new Marked({
      gfm: true,
      renderer: makeRenderers(ctx),
      extensions: [admonitionExtension(locale)],
    })

    let html
    let titleId = null
    let changelog = null
    if (isChangelog) {
      const { intro, sections } = splitChangelog(body)
      const introRender = await renderMarkdown(md, ctx, intro, { dropTitleHeading: true })
      // Timeline = release LINES, not raw sections: stable entries absorb
      // their prerelease cycle as condensed headlines; an in-flight line keeps
      // its newest prerelease entry. Undated sections never publish.
      const versions = []
      for (const line of mergeReleaseLines(releasedSections(sections))) {
        const anchor = ctx.slugger.slug(line.version)
        const bodyMarkdown = line.headlines.length > 0
          ? `${line.body.join('\n')}\n\n### ${PRERELEASE_TITLES[locale]}\n\n${line.headlines.map((headline) => `- **${headline}**`).join('\n')}\n`
          : line.body.join('\n')
        const sectionHtml = (await renderMarkdown(md, ctx, bodyMarkdown)).html
        versions.push({ version: line.version, date: line.date, anchor, html: sectionHtml })
      }
      html = introRender.html
      titleId = introRender.titleId
      changelog = { versions }
    } else {
      const render = await renderMarkdown(md, ctx, body, { dropTitleHeading: true })
      html = render.html
      titleId = render.titleId
    }

    const key = pageKey.replace(/\.md$/, '')
    // The changelog's own TOC is the version timeline — a heading-per-subsection
    // rail (90+ entries) would be noise, so it ships empty.
    const toc = isChangelog
      ? []
      : ctx.headings.filter((h) => h.depth === 2 || h.depth === 3).map(({ depth, text, id }) => ({ depth, text, id }))
    headingIds.set(routePath, new Set(ctx.headings.map((h) => h.id)))
    allLinks.push(...ctx.links.map((link) => ({ from: routePath, ...link })))

    pageEntries.push({
      file: path.join(CONTENT_DIR, 'pages', `${key}.json`),
      data: { frontmatter, html, titleId, toc, ...(changelog ? { changelog } : {}) },
    })
    routeMeta[routePath] = {
      key,
      locale,
      title: String(frontmatter.title ?? ''),
      description: String(frontmatter.description ?? ''),
      lang: String(frontmatter.lang ?? locale),
      changelog: isChangelog,
      toc,
      updatedAt: lastUpdatedFor(root, file),
    }

    // Search: the changelog indexes titles + version headings only (its 250 KB
    // body would double the index for little lookup value); everything else
    // indexes the full stripped text.
    const bodyText = isChangelog ? '' : stripTags(html).replace(/\s+/g, ' ').trim()
    const headingText = isChangelog
      ? changelog.versions.map((v) => `${v.version} ${v.date}`).join(' · ')
      : ctx.headings.map((h) => h.text).join(' · ')
    searchDocs[locale].push({
      id: routePath,
      title: routeMeta[routePath].title,
      breadcrumb: breadcrumbs.get(routePath) ?? '',
      headings: headingText,
      body: bodyText,
    })
  }

  if (missingFiles.length > 0) {
    const list = missingFiles.map((m) => `${m.routePath} → ${m.pageKey}`).join('; ')
    throw new Error(`navigation links to missing page files (fix scripts/navigation.mjs or ship the page): ${list}`)
  }
  for (const link of allLinks) {
    if (!routes.has(link.path)) deadPages.push(link)
    else if (link.hash) {
      const ids = headingIds.get(link.path)
      if (ids && !ids.has(link.hash)) anchorWarns.push({ from: link.from, target: link.path, hash: link.hash })
    }
  }
  if (deadPages.length > 0) {
    const list = [...new Set(deadPages.map((l) => `${l.from} → ${l.raw}`))].join('\n  ')
    throw new Error(`dead internal links (target page is not a published route):\n  ${list}`)
  }
  for (const warn of anchorWarns) console.warn(`[content] anchor not found (warning): ${warn.from}#${warn.hash} → ${warn.target}`)
  if (unlisted.size > 0) log(`not published (no nav/sidebar link reaches them): ${[...unlisted].join(', ')}`)

  const contentDir = path.join(root, CONTENT_DIR)
  await fs.rm(contentDir, { recursive: true, force: true })
  await fs.mkdir(path.join(contentDir, 'pages'), { recursive: true })
  for (const entry of pageEntries) {
    const target = path.join(root, entry.file)
    await fs.mkdir(path.dirname(target), { recursive: true })
    await fs.writeFile(target, `${JSON.stringify(entry.data)}\n`)
  }
  const manifest = {
    generatedAt: new Date().toISOString(),
    siteUrl: SITE_URL,
    routes: routeMeta,
  }
  await fs.writeFile(path.join(contentDir, 'manifest.json'), `${JSON.stringify(manifest)}\n`)
  for (const locale of LOCALES) {
    await fs.writeFile(path.join(contentDir, `search-${locale}.json`), `${JSON.stringify(buildSearchIndex(searchDocs[locale]))}\n`)
  }
  log(`built ${pageEntries.length} pages (${deadPages.length} dead links, ${anchorWarns.length} anchor warnings) → ${CONTENT_DIR}/`)
  return { pages: pageEntries.length, deadLinks: deadPages.length, anchorWarnings: anchorWarns.length, unlisted: [...unlisted] }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  buildContent().catch((error) => {
    console.error(`[content] ${error.message}`)
    process.exitCode = 1
  })
}
